import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("Claim Office - quote base premiums", () => {
  it.todo("empty item list -> premium 5 G (only processing fee)");
  it.todo("single sword -> base 100 + fee 5 = 105 G");
  it.todo("single amulet -> base 60 + fee 5 = 65 G");
  it.todo("single staff -> base 80 + fee 5 = 85 G");
  it.todo("single potion -> base 40 + fee 5 = 45 G");
  it.todo("single rune component -> base 25 + fee 5 = 30 G");
  it.todo("single moonstone component -> base 25 + fee 5 = 30 G");
});

describe("Claim Office - component blocks", () => {
  it.todo("2 runes -> 50 G base premium (+5 fee)");
  it.todo("3 runes -> 60 G base premium block applies (+5 fee)");
  it.todo("4 runes -> 100 G base premium no block (+5 fee)");
  it.todo("7 runes -> 175 G base premium (+5 fee)");
  it.todo("2 runes + 1 moonstone -> 75 G base premium no block different types (+5 fee)");
  it.todo("3 runes + 3 moonstones -> 120 G base premium two separate blocks (+5 fee)");
});

describe("Claim Office - premium modifiers", () => {
  it.todo("cursed sword -> +50% of item base (100+50) +5 fee = 155 G");
  it.todo("highly enchanted sword (ench 5) -> +30% (100+30) +5 fee = 135 G");
  it.todo("sword ench 4 -> no high-enchant surcharge, 100 +5 = 105 G");
  it.todo("cursed + highly enchanted sword (ench 5) -> 100+50+30 +5 = 185 G");
  it.todo("long-standing customer (2 years) -> 20% loyalty discount on policy base");
  it.todo("customer <2 years -> no loyalty discount");
  it.todo("first insurance -> 10% surcharge on policy base");
  it.todo("follow-up contract (2nd quote) -> 15% discount");
});

describe("Claim Office - modifier scope on multi-item policies", () => {
  it.todo("cursed sword + plain amulet -> 160 base + 50 curse = 210 before fee -> 215 G");
});

describe("Claim Office - rounding in MHPCO favor", () => {
  it.todo("premium 197.5 -> rounded up to 198 G");
  it.todo("payout 350.5 -> rounded down to 350 G");
});

describe("Claim Office - integration examples", () => {
  it.todo("newcomer with cursed sword -> 165 G");
  it.todo("long-standing customer second contract cursed sword ench 7 -> 160 G");
});

describe("Claim Office - claim standard reimbursement", () => {
  it.todo("regular sword damage 500 -> payout 400 (minus deductible)");
  it.todo("rune damage 200 -> payout 100 (minus deductible)");
});

describe("Claim Office - claim special clauses", () => {
  it.todo("high-enchant sword (ench 8) dragon material damage 1000 -> payout 400");
  it.todo("dragon-material sword ench 9 damage 1000 -> payout 400 (50% wins then deductible)");
  it.todo("dragon-material sword ench 5 damage 800 -> payout 700 (full then deductible)");
  it.todo("steel sword ench 9 damage 1000 -> payout 400 (high-enchant 50% then deductible)");
});

describe("Claim Office - deductible per damage event", () => {
  it.todo("dragon damages sword 500 + amulet 300 -> payout 600 (deductible per item)");
});

describe("Claim Office - cap", () => {
  it.todo("two swords -> insurance sum 2000, cap 4000");
  it.todo("dragon damages both swords -> each entry separate deductible");
  it.todo("more damages of a type than insured -> reject (non-zero exit)");
  it.todo("sword + amulet -> insurance sum 1600, cap 3200");
  it.todo("cursed sword premium modifiers do not raise cap -> cap 2000");
  it.todo("sword + 3 runes block -> insurance sum 1750, block discount only premium");
  it.todo("successive claims exhaust cap: first 1500->payout 1400 remaining 600");
  it.todo("second claim 1500 -> payout 600 remaining 0 (reduced to remaining cap)");
});

describe("Claim Office - edge cases / errors", () => {
  it.todo("quote unknown item type -> error (non-zero exit)");
  it.todo("claim references item not in policy -> error (non-zero exit)");
  it.todo("claim damage amount -200 -> error (non-zero exit)");
});

