  it.todo("rune damage 200 -> payout 100 (minus deductible)");
});

describe("Claim Office - claim special clauses", () => {
  it.todo("high-enchant sword (ench 8) dragon material damage 1000 -> payout 400");
  it.todo("dragon-material sword ench 9 damage 1000 -> payout 400 (50% wins then deductible)");
  it.todo("dragon-material sword ench 5 damage 800 -> payout 700 (full then deductible)");
  it.todo("steel sword ench 9 damage 1000 -> payout 400 (high-enchant 50% then deductible)");
});

describe("Claim Office - deductible per damage event", () => {
  it.todo("dragon damages sword 500 + amulet 300 -> payout 600 (deductible per item)");
});

describe("Claim Office - cap", () => {
  it.todo("two swords -> insurance sum 2000, cap 4000");
  it.todo("dragon damages both swords -> each entry separate deductible");
  it.todo("more damages of a type than insured -> reject (non-zero exit)");
  it.todo("sword + amulet -> insurance sum 1600, cap 3200");
  it.todo("cursed sword premium modifiers do not raise cap -> cap 2000");
  it.todo("sword + 3 runes block -> insurance sum 1750, block discount only premium");
  it.todo("successive claims exhaust cap: first 1500->payout 1400 remaining 600");
