interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

const CURSE_SURCHARGE = 0.5;
const HIGH_ENCHANT_SURCHARGE = 0.3;
const HIGH_ENCHANT_THRESHOLD = 5;

const itemPremium = (base: number, item: Item): number => {
  let premium = base;
  if (item.cursed) {
    premium += base * CURSE_SURCHARGE;
  }
  if ((item.enchantment ?? 0) >= HIGH_ENCHANT_THRESHOLD) {
    premium += base * HIGH_ENCHANT_SURCHARGE;
  }
  return premium;
};

interface QuoteStep {
  op: "quote";
  items: Item[];
}

type Step = QuoteStep;

interface Customer {
  yearsWithMHPCO: number;
}

interface Scenario {
  customer: Customer;
  steps: Step[];
}

const PROCESSING_FEE = 5;
const LOYALTY_DISCOUNT = 0.2;
const LOYALTY_THRESHOLD = 2;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
const COMPONENT_PREMIUM = 25;
const BLOCK_SIZE = 3;
const BLOCK_PREMIUM = 60;

const componentGroupPremium = (count: number): number => {
  if (count === BLOCK_SIZE) {
    return BLOCK_PREMIUM;
  }
  return count * COMPONENT_PREMIUM;
};

const policyBasePremium = (items: Item[]): number => {
  const componentCounts: Record<string, number> = {};
  let base = 0;
  for (const item of items) {
    if (COMPONENT_TYPES.has(item.type)) {
      componentCounts[item.type] = (componentCounts[item.type] ?? 0) + 1;
    } else {
      base += itemPremium(BASE_PREMIUMS[item.type], item);
    }
  }
  for (const count of Object.values(componentCounts)) {
    base += componentGroupPremium(count);
  }
  return base;
};

const quotePremium = (items: Item[], customer: Customer): number => {
  let premium = policyBasePremium(items);
  if (customer.yearsWithMHPCO >= LOYALTY_THRESHOLD) {
    premium -= premium * LOYALTY_DISCOUNT;
  }
  return premium + PROCESSING_FEE;
};

export const runScenario = (scenario: Scenario): { results: unknown[] } => {
  const results = scenario.steps.map((step) => ({
    premium: quotePremium(step.items, scenario.customer),
  }));
  return { results };
};

