const roundDown = (amount: number): number => Math.floor(amount);

interface Policy {
  items: Item[];
  remainingCap: number;
}

const createPolicy = (items: Item[]): Policy => {
  const insuranceSum = items.reduce(
    (sum, item) => sum + INSURANCE_VALUES[item.type],
    0,
  );
  return { items, remainingCap: insuranceSum * CAP_MULTIPLIER };
};

const damagePayout = (damage: Damage): number => {
  return damage.amount - DEDUCTIBLE;
};

const processClaim = (
  policy: Policy,
  step: ClaimStep,
): { payout: number; remainingCap: number } => {
  const rawPayout = step.incident.damages.reduce(
    (sum, damage) => sum + damagePayout(damage),
    0,
  );
  const payout = Math.min(rawPayout, policy.remainingCap);
  policy.remainingCap -= payout;
  return { payout: roundDown(payout), remainingCap: policy.remainingCap };
};

